{"content":"# Adaptive Rejection Sampling (ARS) after Gilks & Wild (1992)
#
# Reference: Gilks, W. R. & Wild, P. (1992). Adaptive rejection sampling for
#   Gibbs sampling. Applied Statistics 41(2), 337-348.
#
# Design: modular code with consistent `ars.` prefix.
#   ars.logdens      : vectorized log-density from density function g
#   ars.deriv        : central-difference derivative of log-density
#   ars.validate.inputs : input checks
#   ars.find.mode    : locate mode of h on (L, U)
#   ars.init.abscissae : starting abscissae (user or automatic)
#   ars.hull         : upper-hull intersections + envelope weights
#   ars.upper        : evaluate upper hull u(x)
#   ars.lower        : evaluate lower hull l(x)
#   ars.sample.envelope : draw one candidate from envelope s(x)
#   ars              : main sampler
#   test             : formal testing with known truth
#
# The sampler targets log-concave densities only. Non-log-concavity is
# detected by (a) non-decreasing derivatives, (b) intersections out of order,
# (c) log-density above the upper hull, (d) log-density below the lower hull,
# (e) lower hull above upper hull, and (f) improper envelopes on infinite
# domains.

ars.logdens <- function(g, x) {
  gx <- tryCatch(g(x), error = function(e) e)
  if (inherits(gx, "error")) {
    stop(paste0("ars: density function 'g' failed to evaluate: ",
                conditionMessage(gx)))
  }
  if (!is.numeric(gx)) {
    stop("ars: density function 'g' must return a numeric vector")
  }
  if (length(gx) == 1L && length(x) > 1L) {
    # Fall back for non-vectorized densities: evaluate point by point.
    gx <- sapply(x, function(xi) {
      v <- tryCatch(g(xi), error = function(e) NaN)
      if (length(v) != 1L) v <- suppressWarnings(as.numeric(v[1L]))
      if (is.na(v)) return(NaN)
      v
    })
  }
  if (length(gx) != length(x)) {
    stop("ars: density function 'g' must be vectorized: output length must match input length")
  }
  h <- rep(-Inf, length(x))
  bad <- is.na(gx) | is.nan(gx)
  if (any(bad)) {
    # NA/NaN densities are treated as -Inf here; strict checks happen
    # at the abscissae where finiteness is required.
    h[bad] <- -Inf
  }
  pos <- !is.na(gx) & !is.nan(gx) & gx > 0 & is.finite(gx)
  h[pos] <- log(gx[pos])
  infpos <- !is.na(gx) & !is.nan(gx) & is.infinite(gx) & gx > 0
  h[infpos] <- Inf
  # gx == 0 (or negative) stays -Inf; negativity is rejected explicitly
  # at probe points / abscissae by the validators below.
  h
}

ars.deriv <- function(hfun, x) {
  sapply(x, function(xi) {
    h0 <- hfun(xi)
    if (length(h0) != 1L) h0 <- h0[1L]
    if (!is.finite(h0)) return(NaN)
    e0 <- .Machine$double.eps^(1 / 3) * max(1, abs(xi))
    for (scale in c(1, 0.5, 0.25, 0.125)) {
      e <- e0 * scale
      hp <- hfun(xi + e)
      hm <- hfun(xi - e)
      if (length(hp) != 1L) hp <- hp[1L]
      if (length(hm) != 1L) hm <- hm[1L]
      if (is.finite(hp) && is.finite(hm)) return((hp - hm) / (2 * e))
    }
    for (scale in c(1, 0.5, 0.25, 0.125)) {
      e <- e0 * scale
      hp <- hfun(xi + e)
      hm <- hfun(xi - e)
      if (length(hp) != 1L) hp <- hp[1L]
      if (length(hm) != 1L) hm <- hm[1L]
      if (is.finite(hp)) return((hp - h0) / e)
      if (is.finite(hm)) return((h0 - hm) / e)
    }
    NaN
  })
}

ars.validate.inputs <- function(g, n, L, U, x_init) {
  if (missing(g) || !is.function(g)) {
    stop("ars: 'g' must be a function computing the (possibly unnormalized) density in vectorized fashion, e.g. dnorm")
  }
  if (length(n) != 1L || is.na(n) || !is.finite(n) || n < 1 || n != floor(n)) {
    stop("ars: 'n' must be a positive integer (number of points to sample)")
  }
  if (length(L) != 1L || length(U) != 1L || is.na(L) || is.na(U) ||
      !is.numeric(L) || !is.numeric(U)) {
    stop("ars: invalid domain: 'L' and 'U' must be numeric (possibly infinite)")
  }
  if (!(L < U)) {
    stop("ars: invalid domain: require L < U")
  }
  if (!is.null(x_init)) {
    if (!is.numeric(x_init) || any(is.na(x_init)) || any(!is.finite(x_init))) {
      stop("ars: 'x_init' must be finite numeric values strictly inside (L, U)")
    }
    if (length(x_init) < 2L) {
      stop("ars: 'x_init' must contain at least two distinct starting abscissae")
    }
    if (anyDuplicated(x_init) > 0L) {
      stop("ars: 'x_init' must contain distinct values")
    }
    if (any(x_init <= L) || any(x_init >= U)) {
      stop("ars: invalid domain: all 'x_init' must satisfy L < x_init < U")
    }
  }
  # Probe that g works and is a valid (non-negative) density.
  if (is.finite(L) && is.finite(U)) {
    probe <- L + (U - L) * c(0.4, 0.6)
  } else if (is.finite(L)) {
    probe <- L + 1 + c(0, 1)
  } else if (is.finite(U)) {
    probe <- U - 1 - c(1, 0)
  } else {
    probe <- c(0, 1)
  }
  vals <- tryCatch(g(probe), error = function(e) e)
  if (inherits(vals, "error")) {
    stop(paste0("ars: density function 'g' failed to evaluate: ",
                conditionMessage(vals)))
  }
  if (!is.numeric(vals) || any(is.na(vals)) || any(is.nan(vals))) {
    stop("ars: density function 'g' must return numeric (non-NA) values")
  }
  if (length(vals) != length(probe)) {
    stop("ars: density function 'g' must be vectorized: output length must match input length")
  }
  if (any(vals < 0)) {
    stop("ars: density function 'g' must be non-negative")
  }
  invisible(TRUE)
}
","path":"/app/ars.R"}

