ars.find.mode <- function(hfun, L, U) {
  lo <- if (is.finite(L)) L else -10
  hi <- if (is.finite(U)) U else 10
  if (is.finite(L)) {
    eps <- 1e-7 * max(1, abs(L))
    lo <- L + eps
    if (lo >= hi) lo <- L + (U - L) * 0.25
  }
  if (is.finite(U)) {
    eps <- 1e-7 * max(1, abs(U))
    hi <- U - eps
    if (lo >= hi) hi <- U - (U - L) * 0.25
  }
  if (lo >= hi) stop("ars: invalid domain: empty interior (L, U)")
  xm <- NULL
  for (iter in 1:10) {
    opt <- suppressWarnings(stats::optimize(hfun, c(lo, hi), maximum = TRUE))
    xm <- opt$maximum
    at.lo <- abs(xm - lo) < 1e-7 * (abs(lo) + 1)
    at.hi <- abs(xm - hi) < 1e-7 * (abs(hi) + 1)
    expanded <- FALSE
    if (at.lo && !is.finite(L)) {
      lo <- lo * 2
      expanded <- TRUE
    }
    if (at.hi && !is.finite(U)) {
      hi <- hi * 2
      expanded <- TRUE
    }
    if (!expanded) break
  }
  xm
}

ars.init.abscissae <- function(hfun, L, U, x_init) {
  if (!is.null(x_init)) {
    x <- sort(unique(as.numeric(x_init)))
    if (length(x) < 2L) stop("ars: 'x_init' must contain at least two distinct starting abscissae")
    hv <- hfun(x)
    if (any(!is.finite(hv))) {
      stop("ars: density must be positive and finite at all starting abscissae")
    }
    return(x)
  }
  xm <- ars.find.mode(hfun, L, U)
  hm <- hfun(xm)
  if (!is.finite(hm)) {
    stop("ars: could not find a point with positive finite density in (L, U)")
  }
  width <- if (is.finite(L) && is.finite(U)) U - L else Inf
  scale <- if (is.finite(width)) min(1, width / 8) else 1
  if (!(scale > 0) || !is.finite(scale)) scale <- 1
  x <- NULL
  for (attempt in 1:10) {
    offsets <- c(-2, -1, 1, 2) * scale
    cand <- xm + offsets
    # One-sided candidates when the mode sits on a finite boundary
    # (e.g. exponential with mode at L): add interior points.
    if (is.finite(L)) cand <- c(cand, xm + scale * c(0.5, 1.5, 3))
    if (is.finite(U)) cand <- c(cand, xm - scale * c(0.5, 1.5, 3))
    cand <- cand[cand > L & cand < U]
    cand <- sort(unique(c(cand, xm)))
    # Keep points with finite log-density, always keeping the mode.
    hv.cand <- hfun(cand)
    keep <- is.finite(hv.cand)
    keep[cand == xm] <- TRUE
    cand <- cand[keep]
    if (length(cand) >= 2L) {
      # Prefer a small set centred on the mode.
      d <- abs(cand - xm)
      ord <- order(d)
      k <- min(length(cand), 4L)
      x <- sort(cand[ord[1L:k]])
      if (length(x) >= 2L) break else x <- NULL
    }
    scale <- scale / 2
  }
  if (is.null(x) || length(x) < 2L) {
    stop("ars: could not find valid starting abscissae in (L, U)")
  }
  # Enforce bracketing of the mode on unbounded sides by expanding outwards.
  hv <- hfun(x)
  dhv <- ars.deriv(hfun, x)
  for (iter in 1:20) {
    grew <- FALSE
    if (!is.finite(L) && is.finite(dhv[1L]) && dhv[1L] <= 0) {
      step <- max(1, diff(range(x)) / 2, 1)
      cand <- x[1L] - step
      if (cand > L && is.finite(hfun(cand))) {
        x <- c(cand, x)
        hv <- hfun(x)
        dhv <- ars.deriv(hfun, x)
        grew <- TRUE
      } else break
    }
    if (!is.finite(U) && is.finite(dhv[length(dhv)]) && dhv[length(dhv)] >= 0) {
      step <- max(1, diff(range(x)) / 2, 1)
      cand <- x[length(x)] + step
      if (cand < U && is.finite(hfun(cand))) {
        x <- c(x, cand)
        hv <- hfun(x)
        dhv <- ars.deriv(hfun, x)
        grew <- TRUE
      } else break
    }
    if (!grew) break
  }
  sort(unique(x))
}"}

