ars <- function(g, n = 1000L, L = -Inf, U = Inf, x_init = NULL) {
  ars.validate.inputs(g, n, L, U, x_init)
  n <- as.integer(n)
  hfun <- function(x) ars.logdens(g, x)
  x <- ars.init.abscissae(hfun, L, U, x_init)
  hv <- hfun(x)
  dhv <- ars.deriv(hfun, x)
  tol.hull <- 1e-6
  samples <- numeric(n)
  n.accept <- 0L
  iters <- 0L
  max.iters <- 100L * n + 10000L
  while (n.accept < n) {
    iters <- iters + 1L
    if (iters > max.iters) {
      stop("ars: exceeded maximum iterations (density may be non-log-concave or envelope is inefficient)")
    }
    hull <- ars.hull(x, hv, dhv, L, U)
    xstar <- ars.sample.envelope(x, hv, dhv, hull$z, hull$probs)
    if (!is.finite(xstar) || xstar <= L || xstar >= U) next
    ustar <- ars.upper(xstar, x, hv, dhv, hull$z)
    if (!is.finite(ustar)) {
      stop("ars: non-log-concave density detected (non-finite upper hull)")
    }
    lstar <- ars.lower(xstar, x, hv)
    if (is.finite(lstar) && lstar > ustar + tol.hull) {
      stop("ars: non-log-concave density detected (lower hull exceeds upper hull)")
    }
    w <- stats::runif(1)
    if (w <= exp(lstar - ustar)) {
      n.accept <- n.accept + 1L
      samples[n.accept] <- xstar
      next
    }
    hstar <- hfun(xstar)
    if (length(hstar) != 1L) stop("ars: density function returned wrong length at candidate")
    if (is.na(hstar) || is.nan(hstar)) {
      stop("ars: density function returned NA/NaN (invalid density)")
    }
    if (is.infinite(hstar) && hstar > 0) {
      stop("ars: density is infinite at candidate (invalid or non-log-concave density)")
    }
    if (hstar > ustar + tol.hull) {
      stop("ars: non-log-concave density detected (log-density above upper hull)")
    }
    if (is.finite(lstar) && is.finite(hstar) && hstar < lstar - tol.hull) {
      stop("ars: non-log-concave density detected (log-density below lower hull)")
    }
    if (is.finite(hstar)) {
      if (min(abs(x - xstar)) > 1e-12 * max(1, abs(xstar))) {
        dstar <- ars.deriv(hfun, xstar)
        if (is.finite(dstar)) {
          ord <- order(c(x, xstar))
          x <- c(x, xstar)[ord]
          hv <- c(hv, hstar)[ord]
          dhv <- c(dhv, dstar)[ord]
        }
      }
    }
    if (w <= exp(hstar - ustar)) {
      n.accept <- n.accept + 1L
      samples[n.accept] <- xstar
    }
  }
  samples
}"}

