test <- function(n = 2000L,
                 seed = 123,
                 out.normal = "/app/normal_samples.txt",
                 out.exp = "/app/exponential_samples.txt") {
  cat("Running ARS formal tests (seed fixed for reproducibility)...\n")
  npass <- 0L
  nfail <- 0L
  report <- function(name, passed, extra = "") {
    status <- if (isTRUE(passed)) "PASS" else "FAIL"
    if (isTRUE(passed)) npass <<- npass + 1L else nfail <<- nfail + 1L
    if (nzchar(extra)) {
      cat(sprintf("%s: %s %s\n", name, status, extra))
    } else {
      cat(sprintf("%s: %s\n", name, status))
    }
  }
  stat.string <- function(x, em, es) {
    sprintf("(mean=%.4f, sd=%.4f, expected mean=%.4f, sd=%.4f)", mean(x), stats::sd(x), em, es)
  }

  # 1. Standard normal N(0,1): log-concave, unbounded both sides.
  set.seed(seed)
  xn <- tryCatch(ars(dnorm, n = n, L = -Inf, U = Inf), error = function(e) e)
  if (inherits(xn, "error")) {
    report("NORMAL_SAMPLES", FALSE, paste0("(error: ", conditionMessage(xn), ")"))
  } else {
    m <- mean(xn)
    s <- stats::sd(xn)
    ok <- is.finite(m) && is.finite(s) && abs(m - 0) < 0.12 && abs(s - 1) < 0.12
    report("NORMAL_SAMPLES", ok, stat.string(xn, 0, 1))
    # Shape check: not uniform noise. Uniform(-5,5) would have sd ~2.9.
    ok.shape <- is.finite(s) && s < 1.5 && s > 0.6
    report("NORMAL_SHAPE_NOT_UNIFORM", ok.shape, sprintf("(sd=%.4f, uniform would give sd~2.9)", s))
    tryCatch({
      utils::write.table(xn, file = out.normal, row.names = FALSE, col.names = FALSE)
      cat(sprintf("WROTE_NORMAL_SAMPLES: PASS (%s, n=%d)\n", out.normal, length(xn)))
      npass <<- npass + 1L
    }, error = function(e) {
      cat(sprintf("WROTE_NORMAL_SAMPLES: FAIL (%s)\n", conditionMessage(e)))
      nfail <<- nfail + 1L
    })
  }

  # 2. Exponential(1): log-concave, bounded left, unbounded right.
  set.seed(seed + 1L)
  xe <- tryCatch(ars(function(v) stats::dexp(v, rate = 1), n = n, L = 0, U = Inf),
                 error = function(e) e)
  if (inherits(xe, "error")) {
    report("EXPONENTIAL_SAMPLES", FALSE, paste0("(error: ", conditionMessage(xe), ")"))
  } else {
    m <- mean(xe)
    s <- stats::sd(xe)
    ok <- is.finite(m) && is.finite(s) && abs(m - 1) < 0.15 && abs(s - 1) < 0.15 && all(xe >= 0)
    report("EXPONENTIAL_SAMPLES", ok, stat.string(xe, 1, 1))
    tryCatch({
      utils::write.table(xe, file = out.exp, row.names = FALSE, col.names = FALSE)
      cat(sprintf("WROTE_EXPONENTIAL_SAMPLES: PASS (%s, n=%d)\n", out.exp, length(xe)))
      npass <<- npass + 1L
    }, error = function(e) {
      cat(sprintf("WROTE_EXPONENTIAL_SAMPLES: FAIL (%s)\n", conditionMessage(e)))
      nfail <<- nfail + 1L
    })
  }

  # 3. Invalid n (negative count) must be rejected.
  err.n <- tryCatch({ ars(dnorm, n = -5); FALSE }, error = function(e) TRUE)
  report("INVALID_N_REJECTED", isTRUE(err.n))

  # 4. Invalid domain (L >= U) must be rejected.
  err.d <- tryCatch({ ars(dnorm, n = 10, L = 5, U = 2); FALSE }, error = function(e) TRUE)
  report("INVALID_DOMAIN_REJECTED", isTRUE(err.d))

  # 5. Abscissae outside (L, U) must be rejected.
  err.x <- tryCatch({ ars(dnorm, n = 10, L = 0, U = Inf, x_init = c(-1, 1)); FALSE },
                    error = function(e) TRUE)
  report("INVALID_XINIT_REJECTED", isTRUE(err.x))

  # 6. Non-log-concave density must be detected (Cauchy).
  set.seed(seed + 2L)
  err.c <- tryCatch(
    { ars(stats::dcauchy, n = 500L, L = -Inf, U = Inf); FALSE },
    error = function(e) grepl("log-concave", conditionMessage(e), ignore.case = TRUE)
  )
  report("NONLOGCONCAVE_CAUCHY_DETECTED", isTRUE(err.c))

  # 7. Non-log-concave density must be detected (Gamma shape < 1).
  set.seed(seed + 3L)
  err.g <- tryCatch(
    { ars(function(v) stats::dgamma(v, shape = 0.5, rate = 1), n = 500L, L = 0, U = Inf); FALSE },
    error = function(e) grepl("log-concave", conditionMessage(e), ignore.case = TRUE)
  )
  report("NONLOGCONCAVE_GAMMA_DETECTED", isTRUE(err.g))

  # 8. Module: numerical derivative of log-N(0,1) at 0 and 1.
  hnorm <- function(v) ars.logdens(dnorm, v)
  d0 <- ars.deriv(hnorm, 0)
  d1 <- ars.deriv(hnorm, 1)
  ok.d <- is.finite(d0) && is.finite(d1) && abs(d0 - 0) < 1e-3 && abs(d1 + 1) < 1e-3
  report("DERIVATIVE_ACCURACY", ok.d, sprintf("(d(0)=%.5f, d(1)=%.5f, expected 0 and -1)", d0, d1))

  # 9. Module: upper hull bounds truth, lower hull is below truth (normal).
  x0 <- c(-1, 1)
  hv0 <- hnorm(x0)
  dhv0 <- ars.deriv(hnorm, x0)
  hull0 <- tryCatch(ars.hull(x0, hv0, dhv0, -Inf, Inf), error = function(e) e)
  if (inherits(hull0, "error")) {
    report("HULL_BOUNDS_TRUTH", FALSE, paste0("(error: ", conditionMessage(hull0), ")"))
  } else {
    grid <- seq(-3, 3, length.out = 9)
    ht <- hnorm(grid)
    up <- sapply(grid, function(v) ars.upper(v, x0, hv0, dhv0, hull0$z))
    lo <- sapply(grid, function(v) ars.lower(v, x0, hv0))
    ok.u <- all(ht <= up + 1e-6)
    inside <- grid >= min(x0) & grid <= max(x0)
    ok.l <- all(lo[inside] <= ht[inside] + 1e-6)
    report("HULL_BOUNDS_TRUTH", isTRUE(ok.u) && isTRUE(ok.l),
           sprintf("(max truth-upper=%.4f, max lower-truth interior=%.4f)",
                   max(ht - up), max(lo[inside] - ht[inside])))
  }

  cat(sprintf("Done: %d passed, %d failed.\n", npass, nfail))
  invisible(list(passed = npass, failed = nfail))
}"}

